                save_resp_func = globals().get("save_resp_ieduc", globals().get("save_resp"))
                if save_resp_func:
                    save_resp_func(
                        qid="1.1.1",
                        valor=str_valor_111,
                        pontos=pts_111,
                        link=lnk_val,
                        comentario=comentario_simples,
                        comentarios=comentarios_historico
                    )

