def render_questao_2_8_ieduc(res_data: dict, ano_sel: str):
    """Renderiza a Questão 2.8 (Rotatividade do Corpo Docente - Pré-escola)."""
    
    regex_url = globals().get("REGEX_PURE_URL", r'https?://[^\s]+')

