def render_questao_2_14_pre_ieduc(res_data: dict, ano_sel: str):
    """Renderiza a Questão 2.14 (Equilíbrio de Demanda e Oferta de Vagas - Pré-escola)."""
    
    regex_url = globals().get("REGEX_PURE_URL", r'https?://[^\s]+')

